pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public {
        c = new RoundFactory();
        c.initialize();
    }
    function testFuzz_property(address nonOwner, address newOwner) public {
        vm.assume(nonOwner != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(nonOwner != c.owner());

        vm.prank(nonOwner);
        try c.transferOwnership(newOwner) {
        } catch {}

        assertTrue(c.owner() != newOwner);
    }
}
